package com.hengaikj.ai.service;
import com.hengaikj.ai.entity.ApiKeyEntity; import com.hengaikj.ai.mapper.ApiKeyMapper; import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper; import org.springframework.data.redis.core.RedisTemplate; import org.springframework.stereotype.Service; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.time.Instant; import java.util.HexFormat; import java.util.concurrent.TimeUnit;
@Service public class ApiKeyService { private final ApiKeyMapper mapper; private final RedisTemplate<String,Object> redis; public ApiKeyService(ApiKeyMapper m,RedisTemplate<String,Object> r){mapper=m;redis=r;}
 public ApiKeyEntity findActive(String secret,long enterpriseId,long projectId){String hash=hash(secret), key="ha:dev:apikey:"+hash; Object cached=redis.opsForValue().get(key); ApiKeyEntity e=cached instanceof ApiKeyEntity?(ApiKeyEntity)cached:null; if(e==null){e=mapper.selectOne(new QueryWrapper<ApiKeyEntity>().eq("key_hash",hash.getBytes(StandardCharsets.UTF_8)).eq("enterprise_id",enterpriseId).eq("project_id",projectId)); if(e!=null) redis.opsForValue().set(key,e,5,TimeUnit.MINUTES);} if(e==null||!"ENABLED".equals(e.status)||(e.expiresAt!=null&&e.expiresAt.isBefore(Instant.now()))) return null; return e; }
 public static String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
}
